ALTER POLICY "Users can view their own profile" ON public.profiles USING (auth.uid() = id);
ALTER POLICY "Users can update their own profile" ON public.profiles USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
ALTER POLICY "Users can view their own subscriptions" ON public.master_subscriptions USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
ALTER POLICY "Users can view their own payment settings" ON public.payment_settings USING (auth.uid() = user_id);
ALTER POLICY "Users can insert their own payment settings" ON public.payment_settings WITH CHECK (auth.uid() = user_id);
ALTER POLICY "Users can update their own payment settings" ON public.payment_settings USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
ALTER POLICY "Users can delete their own payment settings" ON public.payment_settings USING (auth.uid() = user_id);
CREATE VIEW public.merchant_store_profiles AS SELECT id,store_name,store_slug,store_description,store_logo_url,primary_color,secondary_color,address,address_city,address_state,address_number,address_neighborhood,address_complement,address_zip_code,phone,whatsapp_number,email,about_us_text,about_us_title,return_policy_text,instagram_url,facebook_url,youtube_url,x_url,banner_desktop_url,banner_mobile_url,banner_desktop_urls,banner_mobile_urls,content_banners,main_banner_content,footer_bg_color,footer_text_color,font_family,font_weight,product_image_format,product_border_style,product_text_alignment,product_button_display,button_border_style,button_bg_color,button_text_color,header_logo_position,price_color,title_color,topbar_enabled,topbar_bg_color,topbar_text_color,topbar_text,topbar_link_type,topbar_link_target,store_model,store_layout,selected_benefit_banners,home_video_enabled,home_video_id,home_video_title,home_video_description,home_video_url_original,is_maintenance_mode,source_template_id FROM public.profiles WHERE id=public.merchant_request_store_id() AND public.can_actor_manage_marca_store(auth.uid(),id) WITH LOCAL CHECK OPTION;
GRANT SELECT ON public.merchant_store_profiles TO authenticated;
GRANT UPDATE(store_name,store_description,store_logo_url,primary_color,secondary_color,address,address_city,address_state,address_number,address_neighborhood,address_complement,address_zip_code,phone,whatsapp_number,about_us_text,about_us_title,return_policy_text,instagram_url,facebook_url,youtube_url,x_url,banner_desktop_url,banner_mobile_url,banner_desktop_urls,banner_mobile_urls,content_banners,main_banner_content,footer_bg_color,footer_text_color,font_family,font_weight,product_image_format,product_border_style,product_text_alignment,product_button_display,button_border_style,button_bg_color,button_text_color,header_logo_position,price_color,title_color,topbar_enabled,topbar_bg_color,topbar_text_color,topbar_text,topbar_link_type,topbar_link_target,store_model,store_layout,selected_benefit_banners,home_video_enabled,home_video_id,home_video_title,home_video_description,home_video_url_original,is_maintenance_mode) ON public.merchant_store_profiles TO authenticated;
CREATE VIEW public.merchant_store_payment_settings AS SELECT id,user_id,whatsapp_enabled,whatsapp_number,whatsapp_accepts_cash,whatsapp_accepts_credit,whatsapp_accepts_debit,whatsapp_accepts_pix,whatsapp_accepts_transfer,mercadopago_enabled,mercadopago_public_key,mercadopago_access_token_set,mercadopago_webhook_secret_set,pagbank_enabled,pagbank_email,pagbank_token_set,pagbank_webhook_secret_set,stone_ton_enabled,stone_ton_public_key,stone_ton_merchant_id,stone_ton_secret_key_set,infinitepay_enabled,infinitepay_handle,infinitepay_client_secret_set,infinitepay_webhook_secret_set,pix_enabled,pix_provider,pix_discount_percent,credit_card_enabled,credit_card_provider,credit_card_installments_no_interest,boleto_enabled,boleto_provider FROM public.payment_settings WHERE user_id=public.merchant_request_store_id() AND public.can_actor_manage_marca_store(auth.uid(),user_id) WITH LOCAL CHECK OPTION;
GRANT SELECT ON public.merchant_store_payment_settings TO authenticated;
GRANT UPDATE(whatsapp_enabled,whatsapp_number,whatsapp_accepts_cash,whatsapp_accepts_credit,whatsapp_accepts_debit,whatsapp_accepts_pix,whatsapp_accepts_transfer,mercadopago_enabled,pagbank_enabled,stone_ton_enabled,infinitepay_enabled,pix_enabled,pix_provider,pix_discount_percent,credit_card_enabled,credit_card_provider,credit_card_installments_no_interest,boleto_enabled,boleto_provider) ON public.merchant_store_payment_settings TO authenticated;
CREATE VIEW public.merchant_store_subscriptions AS SELECT id,user_id,plan_id,status,billing_cycle,payment_method,no_charge,current_period_end,created_at,updated_at FROM public.master_subscriptions WHERE user_id=public.merchant_request_store_id() AND public.can_actor_manage_marca_store(auth.uid(),user_id);
GRANT SELECT ON public.merchant_store_subscriptions TO authenticated;
ALTER POLICY "Store owners can view customer addresses" ON public.customer_addresses USING(EXISTS(SELECT 1 FROM public.store_customers sc WHERE sc.customer_id=customer_addresses.customer_id AND sc.store_owner_id=public.merchant_request_store_id()));
COMMENT ON VIEW public.merchant_store_profiles IS 'Explicit operational projection only; auth/account identity fields are never delegated and canonical store_slug remains read-only.';
COMMENT ON VIEW public.merchant_store_payment_settings IS 'Selected-store safe projection; no gateway credential values, secret reads or credential updates are delegated.';
COMMENT ON VIEW public.merchant_store_subscriptions IS 'Read-only selected-store billing history context; no card tokens or provider credentials.';